  let value = n;
  for (let i = 0; i < units.length; i++) {
    if (value < 1024) {
      return `${value} ${units[i]}`;
    }
    value /= 1024;
  }
  // If we reach here, value is >= 1024 TB (i.e., >= 2^50 bytes)
