def roman_to_int(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if s == "":
        raise ValueError("Input cannot be an empty string")

    # Valid characters and their values
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

    # Check for invalid characters
    for ch in s:
        if ch not in values:
            raise ValueError(f"Invalid character '{ch}' in Roman numeral")

    # Check for non-canonical forms (more than 3 repeats of I, X, C, M in a row)
    # We can check this by looking at consecutive identical characters
    i = 0
    while i < len(s):
        count = 1
        while i + count < len(s) and s[i] == s[i + count]:
            count += 1
        if count > 3 and s[i] in 'IXCM':
            raise ValueError(f"Non-canonical numeral: more than 3 repeats of '{s[i]}'")
        i += count

    # Convert to integer
    total = 0
    prev_value = 0
    for ch in s:
        current_value = values[ch]
        if current_value < prev_value:
            total -= current_value
        else:
            total += current_value
        prev_value = current_value

    return total
