def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Quoted field
            j = i + 1
            while j < n:
                if line[j] == '"':
                    if j + 1 < n and line[j + 1] == '"':
                        # Escaped quote
                        j += 1
                    else:
                        # End of quoted field
                        i = j + 1
                        break
                else:
                    j += 1
            else:
                # Reached end of line without closing quote
                raise ValueError("Quoted field not closed")

            # After closing quote, must be comma or end of line
            if i < n and line[i] != ',':
                raise ValueError("Character after closing quote must be comma or end of line")

            fields.append(line[i+1:j])
            i = j
        elif line[i] == ',':
            fields.append('')
            i += 1
        else:
            # Unquoted field
            j = i
            while j < n and line[j] != ',':
                j += 1
            fields.append(line[i:j])
            i = j

    return fields
