                    raise ValueError("Invalid prerelease format")

        # Validate build if present
        build = parts[2] if len(parts) > 2 else None
        if build:
            build_parts = build.split('.')
            for part in build_parts:
                if not part:
                    raise ValueError("Invalid build format")
                if not re.match(r'^[0-9A-Za-z-]+$', part):
                    raise ValueError("Invalid build format")

        return (major_minor_patch, prerelease, build)

    try:
        a_parsed = parse_version(a)
    except ValueError:
        raise ValueError(f"Invalid version: {a}")

    try:
        b_parsed = parse_version(b)
    except ValueError:
        raise ValueError(f"Invalid version: {b}")

    # Compare major.minor.patch
    for i in range(3):
        if a_parsed[0][i] < b_parsed[0][i]:
            return -1
        elif a_parsed[0][i] > b_parsed[0][i]:
            return 1

    # Compare prerelease
    prerelease_a = a_parsed[1]
    prerelease_b = b_parsed[1]

    if prerelease_a is None and prerelease_b is None:
        return 0
    elif prerelease_a is None:
        return 1  # No prerelease > has prerelease
    elif prerelease_b is None:
        return -1  # Has prerelease < no prerelease

    # Compare prerelease parts
    parts_a = prerelease_a.split('.')
    parts_b = prerelease_b.split('.')

    min_len = min(len(parts_a), len(parts_b))

    for i in range(min_len):
        part_a = parts_a[i]
        part_b = parts_b[i]

        # Check if both are all digits
        a_is_digit = part_a.isdigit()
        b_is_digit = part_b.isdigit()

        if a_is_digit and b_is_digit:
            # Compare numerically
            if int(part_a) < int(part_b):
                return -1
            elif int(part_a) > int(part_b):
                return 1
        elif a_is_digit and not b_is_digit:
            # All-digit < alphanumeric
            return -1
        elif not a_is_digit and b_is_digit:
            # Alphanumeric > all-digit
            return 1
        else:
            # Both alphanumeric, compare lexicographically
            if part_a < part_b:
                return -1
            elif part_a > part_b:
                return 1

    # If all shared parts are equal, longer prerelease has higher precedence
    if len(parts_a) > len(parts_b):
        return 1
    elif len(parts_a) < len(parts_b):
        return -1

    return 0
