def rle_encode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if any(c.isdigit() for c in s):
        raise ValueError("Input must not contain digit characters")
    if not s:
        return ""
    result = []
    i = 0
    while i < len(s):
        char = s[i]
        count = 1
        while i + count < len(s) and s[i + count] == char:
            count += 1
        result.append(f"{count}{char}")
        i += count
    return "".join(result)

def rle_decode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if not s:
        return ""
    result = []
    i = 0
    while i < len(s):
        # Extract count
        j = i
        while j < len(s) and s[j].isdigit():
            j += 1
        if j == i:
            raise ValueError("Missing count")
        count_str = s[i:j]
        count = int(count_str)
        if count == 0:
            raise ValueError("Count must be at least 1")
        i = j
        # Extract character
        if i >= len(s):
            raise ValueError("Trailing digits with no character")
        char = s[i]
        if char.isdigit():
            raise ValueError("Character must be non-digit")
        i += 1
        result.append(char * count)
    return "".join(result)
