        raise ValueError("missing colon")

    hour_str, minute_str = time_part.split(':', 1)

    if not hour_str or not minute_str:
        raise ValueError("missing hour or minutes")

    # Validate hour
    hour = int(hour_str)
    if hour < 1 or hour > 12:
        raise ValueError(f"hour must be between 1 and 12, got {hour}")

    # Validate minutes
    if len(minute_str) != 2 or not minute_str.isdigit():
        raise ValueError("minutes must be exactly two digits")
    minute = int(minute_str)
    if minute < 0 or minute > 59:
        raise ValueError(f"minutes must be between 00 and 59, got {minute}")

    # Validate suffix
    if not suffix:
        raise ValueError("missing AM/PM suffix")

    suffix_upper = suffix.upper()
    if suffix_upper not in ("AM", "PM"):
        raise ValueError(f"unknown suffix: {suffix}")

    # Convert to 24-hour format
    if hour == 12:
        if suffix_upper == "AM":
            hour_24 = 0
        else:
            hour_24 = 12
    else:
        if suffix_upper == "PM":
            hour_24 = hour + 12
        else:
            hour_24 = hour

    return f"{hour_24:02d}:{minute:02d}"

